namespace App\Jobs;

use App\Models\Project;
use App\Services\HelmDeploymentService;
use Illuminate\Bus\Queueable;
use Illuminate\Contracts\Queue\ShouldQueue;
use Illuminate\Foundation\Bus\Dispatchable;
use Illuminate\Auth\Access\AuthorizationException;

class DeployKubeManifestJob implements ShouldQueue
{
    use Dispatchable, Queueable;

    public function __construct(public int $projectId, public int $clusterId, public string $manifestYaml)
    {
    }

    public function handle(HelmDeploymentService $helmService): void
    {
        $project = Project::findOrFail($this->projectId);
        $cluster = $project->kubernetesClusters()->findOrFail($this->clusterId);

        $helmService->applyManifest($cluster, $this->manifestYaml);
    }
}
